-- 4. Записи в Гостевой книге
INSERT OR REPLACE INTO guestbook (id, author, city, message, admin_reply, status) VALUES
('gb-01', 'Алексей П.', 'Москва', 'Спасибо Никитке за быструю починку компьютера! Синий экран вылетал каждые 10 минут, думал сгорела видеокарта. Оказалось просто высохла термопаста и забился пылью кулер. Почистил всё за полчаса, теперь летает!', 'Рад был помочь, Алексей! Не забывайте продувать пыль хотя бы раз в полгода!', 'approved'),
('gb-02', 'Gamer_X', 'Москва', 'Привет! Поменял вчера диск S.T.A.L.K.E.R. на Half-Life 2. Диск в идеальном состоянии, без царапин, установка прошла без ошибок. Респект Никитке! Есть ли в наличии Warcraft 3?', 'Привет! Да, Warcraft III: Frozen Throne есть на CD-ROM, заходи в гости, обменяемся!', 'approved'),
('gb-03', 'Елена Сергеевна', 'Москва', 'Очень благодарна за помощь в сборке ПК для сына. Собрал за 1 день, все кабели аккуратно уложены, системы работают шустро. И недорого!', 'Спасибо за отзыв, Елена Сергеевна! Пусть компьютер служит долго и приносит только радость!', 'approved'),
('gb-04', 'Dimon_2007', 'Москва', 'Поставил Windows XP SP3 с вашего диска. Все драйверы на материнку подтянулись сами! Продавцу респект!', 'Отлично, Димон! Заходи за свежими кодеками!', 'approved'),
('gb-05', 'Колян_99', 'Москва', 'Обменялся диском S.T.A.L.K.E.R. Диск идеальный, спасибо мастерской за честный обмен 1 к 1!', 'Всегда рады! Заходи за Heroes V!', 'approved'),
('gb-06', 'SysAdmin_Max', 'Москва', 'Классный дизайн сайта! Настоящий ретро-стиль как во времена диалапа и Rambler TOP100!', 'Спасибо! Стараемся поддерживать дух первого веб-интернета!', 'approved');

