INSERT OR REPLACE INTO forum_topics (id, category_id, author_id, title, is_pinned, is_closed) VALUES
('top-advice-01', 'cat-03', 'usr-admin-01', '📌 [СОВЕТ МАСТЕРА] Топ-5 настроек Windows XP SP3 для максимальной скорости в играх!', 1, 0),
('top-faq-01', 'cat-03', 'usr-admin-01', '📌 [F.A.Q. / ВОПРОС-ОТВЕТ] Что делать при вылете Синего Экрана Смерти (BSOD 0x000000D1)?', 1, 0),
('top-01', 'cat-01', 'usr-gamer-02', 'Что лучше для игр 2007 года: Core 2 Duo E6600 или Athlon 64 X2 6000+?', 0, 0),
('top-02', 'cat-02', 'usr-alex-03', 'Ищу диск с оригинальной GTA III в переводе Бука! Обменяю на Heroes V.', 0, 0);

INSERT OR REPLACE INTO forum_posts (id, topic_id, author_id, content) VALUES
('post-adv-01', 'top-advice-01', 'usr-admin-01', 'Привет всем ретро-геймерам! Как администратор и компьютерный мастер с 2001 года, даю вам 5 золотых советов по оптимизации вашей системы: [b]1. Отключите ненужные службы[/b] в msconfig (Служба индексирования, Автоматическое обновление). [b]2. Размер файла подкачки (pagefile.sys)[/b]: установите фиксированный размер (1.5x от объёма вашей ОЗУ DDR2). [b]3. Кодеки и видео[/b]: ставьте только [code]K-Lite Codec Pack 3.90 Full[/code] — идеален для KMPlayer и Winamp 2.x! [b]4. Очистка от пыли[/b]: раз в полгода меняйте термопасту КПТ-8 на процессоре LGA775 и видеокарте AGP! [b]5. Задавайте вопросы[/b]: пишите любые вопросы по железу прямо в этот раздел!'),
('post-adv-02', 'top-advice-01', 'usr-gamer-02', 'Спасибо огромнейшее Никитке за совет! Отключил индексацию — Windows XP стала загружаться за 12 секунд!'),
('post-faq-01', 'top-faq-01', 'usr-admin-01', 'Разбираем самую частую проблему 2000-х годов — Синий Экран Смерти: [quote]Код ошибки: DRIVER_IRQL_NOT_LESS_OR_EQUAL (0x000000D1)[/quote] [b]Причина:[/b] Конфликт драйверов NVIDIA ForceWare/ATI Catalyst или перегрев чипсета/плашек оперативной памяти. [b]Решение от Мастера Никитки:[/b] 1. Проверьте плашки ОЗУ утилитой MemTest86. 2. Переустановите драйвер видеокарты с полной очисткой через Driver Cleaner. 3. Если вылет повторяется — звоните 8 (900) 200-07-07, привозите системник ко мне на радиорынок, всё настроим!'),
('post-01', 'top-01', 'usr-gamer-02', 'Народ, собираю ПК под S.T.A.L.K.E.R. и Crysis. Стою перед выбором проца: Интел Core 2 Duo E6600 или АМД Athlon 64 X2 6000+? Видеокарта будет GeForce 8800 GTS.'),
('post-02', 'top-01', 'usr-admin-01', 'Привет! Core 2 Duo архитектуры Conroe разгоняется намного лучше и меньше греется. Бери E6600 и материнку на чипсете P35, не пожалеешь!'),
('post-03', 'top-02', 'usr-alex-03', 'Мужики, очень нужен лицензионный диск GTA 3. Готов отдать в обмен отличный диск Heroes of Might and Magic V в боксе!');

